import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# GELU approximation: 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
# Exact GELU: 0.5 * x * (1 + erf(x / sqrt(2)))

fused_ops_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_bias_div_gelu_kernel(float* out, const float* bias, float divisor, int rows, int cols) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = rows * cols;
    if (idx < total_elements) {
        int col = idx % cols;
        float val = (out[idx] + bias[col]) / divisor;
        // Exact GELU: 0.5 * val * (1.0f + erf(val / sqrt(2.0f)))
        out[idx] = 0.5f * val * (1.0f + erff(val * 0.70710678118f));
    }
}

void fused_bias_div_gelu(torch::Tensor out, torch::Tensor bias, float divisor) {
    int rows = out.size(0);
    int cols = out.size(1);
    int total_elements = rows * cols;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_bias_div_gelu_kernel<<<num_blocks, block_size>>>(
        out.data_ptr<float>(),
        bias.data_ptr<float>(),
        divisor,
        rows,
        cols
    );
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_source,
    functions=["fused_bias_div_gelu"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused_ops = fused_ops

    def forward(self, x):
        # Perform matrix multiplication
        # We use torch.mm because we'll handle the bias in the fused kernel.
        # However, torch.mm doesn't include the weight transpose, so we use weight.T
        # and we need to be careful with the memory layout.

        # x is (batch_size, input_size)
        # self.linear.weight is (output_size, input_size)
        # We need (batch_size, input_size) @ (input_size, output_size)

        # Use torch.mm for the GEMM part
        out = torch.mm(x, self.linear.weight.t())

        # Use our custom kernel for fused bias addition, division, and GELU
        self.fused_ops.fused_bias_div_gelu(out, self.linear.bias, float(self.divisor))

        return out

def get_inputs():
    batch_size = 1024
    input_size = 8192
    return [torch.rand(batch_size, input_size).cuda()]

def get_init_inputs():
    input_size = 8192
    output_size = 8192
    divisor = 10.0
    return [input_size, output_size, divisor]

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

fused_ops_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int pool_size,
    float s1,
    float s2) {

    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int nc = blockIdx.z;

    if (ow < out_w && oh < out_h && nc < batch_size * channels) {
        int n = nc / channels;
        int c = nc % channels;

        float sum = 0.0f;
        for (int i = 0; i < pool_size; ++i) {
            for (int j = 0; j < pool_size; ++j) {
                int ih = oh * pool_size + i;
                int iw = ow * pool_size + j;

                if (ih < in_h && iw < in_w) {
                    float val = input[((n * channels + c) * in_h + ih) * in_w + iw];
                    val = tanhf(val - s1) - s2;
                    sum += val;
                }
            }
        }
        output[((n * channels + c) * out_h + oh) * out_w + ow] = sum / (pool_size * pool_size);
    }
}

torch::Tensor fused_ops_hip(
    torch::Tensor input,
    int pool_size,
    float s1,
    float s2) {

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_h = in_h / pool_size;
    int out_w = in_w / pool_size;

    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    dim3 block_dim(16, 16);
    dim3 grid_dim((out_w + block_dim.x - 1) / block_dim.x, 
                   (out_h + block_dim.y - 1) / block_dim.y, 
                   batch_size * channels);

    fused_ops_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_h,
        in_w,
        out_h,
        out_w,
        pool_size,
        s1,
        s2
    );

    return output;
}
"""

fused_ops_module = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_kernel_source,
    functions=["fused_ops_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size).cuda()
        self.subtract1_value = subtract1_value
        self.subtract2_value = subtract2_value
        self.kernel_size_pool = kernel_size_pool
        self.fused_ops = fused_ops_module

    def forward(self, x):
        x = self.conv(x)
        x = self.fused_ops.fused_ops_hip(x, self.kernel_size_pool, self.subtract1_value, self.subtract2_value)
        return x

def get_inputs():
    batch_size = 128
    in_channels = 64
    height, width = 128, 128
    return [torch.rand(batch_size, in_channels, height, width).cuda()]

def get_init_inputs():
    in_channels = 64
    out_channels = 128
    kernel_size = 3
    subtract1_value = 0.5
    subtract2_value = 0.2
    kernel_size_pool = 2
    return [in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool]

