swish_scaling_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void swish_scaling_kernel(float* x, float scaling_factor, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        // Swish: x * sigmoid(x) = x / (1 + exp(-x))
        float swish = val / (1.0f + expf(-val));
        x[idx] = swish * scaling_factor;
    }
}

void swish_scaling_hip(torch::Tensor x, float scaling_factor) {
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    swish_scaling_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        scaling_factor,
        size
    );
}
"""

swish_scaling_lib = load_inline(
    name="swish_scaling",
    cpp_sources=swish_scaling_source,
    functions=["swish_scaling_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        # Perform matrix multiplication (includes bias addition)
        x = self.matmul(x)
        # Apply fused Swish activation and scaling in-place
        swish_scaling_lib.swish_scaling_hip(x, self.scaling_factor)
        return x

