fused_gelu_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>
#include <hip/hip_fp16.h>

#define SOFTMAX_BLOCK_SIZE 256

__device__ inline float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

__global__ void gelu_softmax_kernel(const float* input, float* output, int rows, int cols) {
    int row = blockIdx.x;
    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    __shared__ float shared_max[SOFTMAX_BLOCK_SIZE];
    __shared__ float shared_sum[SOFTMAX_BLOCK_SIZE];

    float local_max = -1e20f;
    for (int i = threadIdx.x; i < cols; i += SOFTMAX_BLOCK_SIZE) {
        float val = gelu(row_input[i]);
        if (val > local_max) local_max = val;
    }

    shared_max[threadIdx.x] = local_max;
    __syncthreads();

    for (int stride = SOFTMAX_BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_max[threadIdx.x] = fmaxf(shared_max[threadIdx.x], shared_max[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    float max_val = shared_max[0];

    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < cols; i += SOFTMAX_BLOCK_SIZE) {
        float val = expf(gelu(row_input[i]) - max_val);
        local_sum += val;
    }

    shared_sum[threadIdx.x] = local_sum;
    __syncthreads();

    for (int stride = SOFTMAX_BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }
    float sum_val = shared_sum[0];

    for (int i = threadIdx.x; i < cols; i += SOFTMAX_BLOCK_SIZE) {
        row_output[i] = expf(gelu(row_input[i]) - max_val) / sum_val;
    }
}

torch::Tensor gelu_softmax_hip(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);
    auto output = torch::empty_like(input);

    dim3 grid(rows);
    dim3 block(SOFTMAX_BLOCK_SIZE);

    hipLaunchKernelGGL(gelu_softmax_kernel, grid, block, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_gelu_softmax_source,
    functions=["gelu_softmax_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(in_features, out_features).cuda()

    def forward(self, x):
        x = self.linear(x)
        x = fused_ops.gelu_softmax_hip(x)
        return x

