instance_norm_divide_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void instance_norm_divide_kernel(
    float* __restrict__ input,
    int N, int C, int H, int W,
    float eps, float divide_by) {

    int nc = blockIdx.x; // index for (n, c)
    if (nc >= N * C) return;

    int hw_size = H * W;
    float* input_ptr = input + nc * hw_size;

    // Step 1: Compute sum and sum of squares
    float sum = 0.0f;
    float sum_sq = 0.0f;

    for (int i = threadIdx.x; i < hw_size; i += blockDim.x) {
        float val = input_ptr[i];
        sum += val;
        sum_sq += val * val;
    }

    // Block-level reduction for sum and sum_sq
    // Using simple shared memory reduction
    extern __shared__ float shared_data[];
    float* s_sum = shared_data;
    float* s_sum_sq = shared_data + blockDim.x;

    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = s_sum[0] / hw_size;
    float var = (s_sum_sq[0] / hw_size) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    float inv_std = 1.0f / (sqrtf(var + eps) * divide_by);

    // Step 2: Normalize and divide
    for (int i = threadIdx.x; i < hw_size; i += blockDim.x) {
        input_ptr[i] = (input_ptr[i] - mean) * inv_std;
    }
}

torch::Tensor instance_norm_divide_hip(torch::Tensor input, float eps, float divide_by) {
    int N = input.size(0);
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    const int block_size = 256;
    int num_blocks = N * C;
    int shared_mem_size = 2 * block_size * sizeof(float);

    instance_norm_divide_kernel<<<num_blocks, block_size, shared_mem_size>>>(
        input.data_ptr<float>(), N, C, H, W, eps, divide_by);

    return input;
}
"""

instance_norm_divide_lib = load_inline(
    name="instance_norm_divide",
    cpp_sources=instance_norm_divide_source,
    functions=["instance_norm_divide_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, divide_by):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size).cuda()
        self.divide_by = divide_by
        self.eps = 1e-5 # Default for InstanceNorm2d

    def forward(self, x):
        x = self.conv(x)
        # Note: In-place operation for efficiency if possible
        x = instance_norm_divide_lib.instance_norm_divide_hip(x.contiguous(), self.eps, float(self.divide_by))
        return x

