mish_kernel_code = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__device__ inline float mish_forward(float x) {
    // Mish(x) = x * tanh(softplus(x))
    // softplus(x) = log(1 + exp(x))
    // For x > 20, softplus(x) is approx x, and tanh(x) is approx 1
    if (x > 20.0f) {
        return x;
    }
    // For x < -20, exp(x) is very small, softplus(x) is approx exp(x),
    // tanh(exp(x)) is approx exp(x)
    if (x < -20.0f) {
        return x * expf(x);
    }
    float softplus = log1pf(expf(x));
    return x * tanhf(softplus);
}

__global__ void mish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        output[idx] = mish_forward(input[idx]);
    }
}

torch::Tensor mish_hip(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    mish_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}
"""

mish_lib = load_inline(
    name="mish_lib",
    cpp_sources=mish_kernel_code,
    functions=["mish_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)

    def forward(self, x):
        x = self.conv(x)
        x = mish_lib.mish_hip(x)
        x = self.bn(x)
        return x

