fused_ops_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <algorithm>

__device__ inline float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int out_features,
    int pool_kernel_size,
    float scale_factor,
    int num_pooled) {

    int row = blockIdx.x;
    if (row >= batch_size) return;

    extern __shared__ float shared_data[];

    float max_val = -1e20f;

    // Each thread calculates one or more pooled values
    for (int i = threadIdx.x; i < num_pooled; i += blockDim.x) {
        float sum = 0.0f;
        int start_idx = i * pool_kernel_size;
        for (int k = 0; k < pool_kernel_size; ++k) {
            sum += input[row * out_features + start_idx + k];
        }
        float avg = sum / (float)pool_kernel_size;
        float val = gelu(avg) * scale_factor;
        if (val > max_val) max_val = val;
    }

    // Now reduce max_val within the block
    shared_data[threadIdx.x] = max_val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared_data[threadIdx.x] = fmaxf(shared_data[threadIdx.x], shared_data[threadIdx.x + stride]);
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[row] = shared_data[0];
    }
}

torch::Tensor fused_ops_hip(torch::Tensor input, int pool_kernel_size, float scale_factor) {
    int batch_size = input.size(0);
    int out_features = input.size(1);
    int num_pooled = out_features / pool_kernel_size;

    auto output = torch::empty({batch_size}, input.options());

    int block_size = 256;
    if (num_pooled < block_size) {
        // Adjust block size if num_pooled is small, but 256 is usually fine.
    }

    dim3 grid(batch_size);
    dim3 block(block_size);
    int shared_mem_size = block_size * sizeof(float);

    fused_ops_kernel<<<grid, block, shared_mem_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features,
        pool_kernel_size,
        scale_factor,
        num_pooled
    );

    return output;
}
"""

fused_ops_lib = load_inline(
    name="fused_ops_lib",
    cpp_sources=fused_ops_cpp_source,
    functions=["fused_ops_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.pool_kernel_size = pool_kernel_size
        self.scale_factor = scale_factor
        self.fused_ops_lib = fused_ops_lib

    def forward(self, x):
        x = self.matmul(x)
        return self.fused_ops_lib.fused_ops_hip(x, self.pool_kernel_size, self.scale_factor)

import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os

os.environ["CXX"] = "hipcc"

# HIP kernel for fused Tanh, Scaling, Bias addition, and Max-pooling
fused_ops_kernel_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_pool_kernel(
    const float* __restrict__ input,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int pool_size,
    float scaling_factor) 
{
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * channels * out_h * out_w;

    if (tid < total_elements) {
        int ow = tid % out_w;
        int oh = (tid / out_w) % out_h;
        int c = (tid / (out_w * out_h)) % channels;
        int n = tid / (out_w * out_h * channels);

        int start_h = oh * pool_size;
        int start_w = ow * pool_size;

        float max_val = -1e38f; // Very small value

        for (int ph = 0; ph < pool_size; ++ph) {
            for (int pw = 0; pw < pool_size; ++pw) {
                int ih = start_h + ph;
                int iw = start_w + pw;
                if (ih < in_h && iw < in_w) {
                    float val = input[((n * channels + c) * in_h + ih) * in_w + iw];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }

        // Apply tanh, scaling, and bias to the max value
        // f(x) = tanh(x) * scaling + bias
        float res = tanhf(max_val) * scaling_factor + bias[c];
        output[tid] = res;
    }
}

torch::Tensor fused_pool_hip(
    torch::Tensor input,
    torch::Tensor bias,
    int pool_size,
    float scaling_factor) 
{
    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_h = in_h / pool_size;
    int out_w = in_w / pool_size;

    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    int total_elements = batch_size * channels * out_h * out_w;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_pool_kernel, dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_h,
        in_w,
        out_h,
        out_w,
        pool_size,
        scaling_factor
    );

    return output;
}
"""

