fused_bn_scale_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_bn_scale_kernel(
    const float* __restrict__ input,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    float scaling_factor,
    float eps,
    int batch_size,
    int channels,
    int height,
    int width) {

    int nc = blockIdx.x * blockDim.x + threadIdx.x;
    int total_channels = batch_size * channels;

    if (nc < total_channels) {
        int c = nc % channels;
        float mean = running_mean[c];
        float var = running_var[c];
        float w = weight[c];
        float b = bias[c];

        float inv_std = 1.0f / sqrtf(var + eps);
        float factor = w * inv_std * scaling_factor;
        float offset = (b - mean * w * inv_std) * scaling_factor;

        int channel_offset = nc * height * width;
        for (int hw = 0; hw < height * width; ++hw) {
            output[channel_offset + hw] = input[channel_offset + hw] * factor + offset;
        }
    }
}

torch::Tensor fused_bn_scale_hip(
    torch::Tensor input,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor weight,
    torch::Tensor bias,
    float scaling_factor,
    float eps) {

    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);

    auto output = torch::empty_like(input);

    int total_channels = batch_size * channels;
    int threads_per_block = 256;
    int blocks = (total_channels + threads_per_block - 1) / threads_per_block;

    hipLaunchKernelGGL(fused_bn_scale_kernel, blocks, threads_per_block, 0, 0,
        input.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        eps,
        batch_size,
        channels,
        height,
        width
    );

    return output;
}
"""

