# HIP kernel for fused bias + max_pool + sum + scale
fused_op_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <float.h>

__global__ void fused_op_kernel(const float* __restrict__ Z, const float* __restrict__ bias, float* __restrict__ out, 
                                int batch_size, int out_features, int kernel_size, float scale_factor) {
    int b = blockIdx.x; // each block handles one batch
    if (b >= batch_size) return;

    int pooled_features = out_features / kernel_size;
    float batch_sum = 0.0f;

    for (int i = 0; i < pooled_features; ++i) {
        float max_val = -FLT_MAX;
        for (int k = 0; k < kernel_size; ++k) {
            int idx = i * kernel_size + k;
            if (idx < out_features) {
                float val = Z[b * out_features + idx] + bias[idx];
                if (val > max_val) {
                    max_val = val;
                }
            }
        }
        batch_sum += max_val;
    }
    out[b] = batch_sum * scale_factor;
}

torch::Tensor fused_op_hip(torch::Tensor Z, torch::Tensor bias, int kernel_size, float scale_factor) {
    auto batch_size = Z.size(0);
    auto out_features = Z.size(1);
    auto out = torch::empty({batch_size}, Z.options());

    const int num_blocks = batch_size;
    const int block_size = 1; // We'll use 1 thread per batch for simplicity, but could optimize

    fused_op_kernel<<<num_blocks, 1>>>(Z.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), 
                                       batch_size, out_features, kernel_size, scale_factor);

    return out;
}

// Optimized fused kernel with better parallelism
__global__ void fused_op_kernel_v2(const float* __restrict__ Z, const float* __restrict__ bias, float* __restrict__ out, 
                                   int batch_size, int out_features, int kernel_size, float scale_factor) {
    extern __shared__ float shared_data[];

    int b = blockIdx.x; // batch index
    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    int pooled_features = out_features / kernel_size;
    float local_sum = 0.0f;

    for (int i = tid; i < pooled_features; i += num_threads) {
        float max_val = -FLT_MAX;
        for (int k = 0; k < kernel_size; ++k) {
            int idx = i * kernel_size + k;
            float val = Z[b * out_features + idx] + bias[idx];
            if (val > max_val) {
                max_val = val;
            }
        }
        local_sum += max_val;
    }

    // Reduce local_sum within the block
    shared_data[tid] = local_sum;
    __syncthreads();

    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[b] = shared_data[0] * scale_factor;
    }
}

torch::Tensor fused_op_hip_v2(torch::Tensor Z, torch::Tensor bias, int kernel_size, float scale_factor) {
    auto batch_size = Z.size(0);
    auto out_features = Z.size(1);
    auto out = torch::empty({batch_size}, Z.options());

    const int block_size = 256;
    const int num_blocks = batch_size;

    fused_op_kernel_v2<<<num_blocks, block_size, block_size * sizeof(float)>>>(
        Z.data_ptr<float>(), bias.data_ptr<float>(), out.data_ptr<float>(), 
        batch_size, out_features, kernel_size, scale_factor);

    return out;
}
"""

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_op_cpp_source,
    functions=["fused_op_hip_v2"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.kernel_size = kernel_size
        self.scale_factor = scale_factor
        self.fused_op = fused_op

    def forward(self, x):
        # We compute Z = x @ weight.T without bias
        # PyTorch's matmul is very efficient.
        Z = torch.matmul(x, self.matmul.weight.t())
        # Then use our fused kernel to add bias, max pool, sum, and scale
        return self.fused_op.fused_op_hip_v2(Z, self.matmul.bias, self.kernel_size, self.scale_factor)

