# HIP kernel for fused bias addition, dropout, and softmax
fused_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>
#include <hiprand/hiprand_kernel.h>

__global__ void fused_bias_dropout_softmax_kernel(
    float* x, 
    const float* bias, 
    float dropout_p, 
    bool training, 
    int rows, 
    int cols,
    unsigned long long seed) 
{
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    extern __shared__ float shared_data[];
    float* shared_max = shared_data;
    float* shared_sum = shared_data + num_threads;

    // 1. Add bias and find max
    float local_max = -INFINITY;
    for (int col = tid; col < cols; col += num_threads) {
        float val = x[row * cols + col] + bias[col];

        // Dropout
        if (training && dropout_p > 0.0f) {
            hiprandState_t state;
            hiprand_init(seed, row * cols + col, 0, &state);
            if (hiprand_uniform(&state) < dropout_p) {
                val = 0.0f;
            } else {
                val = val / (1.0f - dropout_p);
            }
        }

        x[row * cols + col] = val; // Store back for next passes
        if (val > local_max) local_max = val;
    }

    // Block reduction for max
    shared_max[tid] = local_max;
    __syncthreads();
    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (shared_max[tid + s] > shared_max[tid]) {
                shared_max[tid] = shared_max[tid + s];
            }
        }
        __syncthreads();
    }
    float max_val = shared_max[0];

    // 2. Compute sum of exps
    float local_sum = 0.0f;
    for (int col = tid; col < cols; col += num_threads) {
        float val = expf(x[row * cols + col] - max_val);
        x[row * cols + col] = val; // Temporarily store exp(x-max)
        local_sum += val;
    }

    // Block reduction for sum
    shared_sum[tid] = local_sum;
    __syncthreads();
    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }
    float sum_val = shared_sum[0];

    // 3. Normalize
    for (int col = tid; col < cols; col += num_threads) {
        x[row * cols + col] = x[row * cols + col] / sum_val;
    }
}

torch::Tensor fused_bias_dropout_softmax_hip(
    torch::Tensor x, 
    torch::Tensor bias, 
    float dropout_p, 
    bool training,
    unsigned long long seed) 
{
    int rows = x.size(0);
    int cols = x.size(1);

    const int threads_per_block = 1024;
    size_t shared_mem_size = 2 * threads_per_block * sizeof(float);

    fused_bias_dropout_softmax_kernel<<<rows, threads_per_block, shared_mem_size>>>(
        x.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        dropout_p, 
        training, 
        rows, 
        cols,
        seed
    );

    return x;
}
"""

