#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__device__ __forceinline__ float gelu_func(float x) {
    return 0.5f * x * (1.0f + erff(x * 0.70710678118f));
}

__global__ void fused_bias_div_gelu_kernel_vec4(float* out, const float* bias, float divisor, int rows, int cols) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    int total_elements = rows * cols;
    if (idx + 3 < total_elements) {
        float4 val_vec = reinterpret_cast<float4*>(&out[idx])[0];

        // We assume cols is a multiple of 4, which 8192 is.
        int col = idx % cols;
        float4 bias_vec = reinterpret_cast<const float4*>(&bias[col])[0];

        float4 res;
        res.x = gelu_func((val_vec.x + bias_vec.x) / divisor);
        res.y = gelu_func((val_vec.y + bias_vec.y) / divisor);
        res.z = gelu_func((val_vec.z + bias_vec.z) / divisor);
        res.w = gelu_func((val_vec.w + bias_vec.w) / divisor);

        reinterpret_cast<float4*>(&out[idx])[0] = res;
    } else {
        // Handle remainder
        for (int i = idx; i < total_elements; ++i) {
            int col = i % cols;
            float val = (out[i] + bias[col]) / divisor;
            out[i] = gelu_func(val);
        }
    }
}

