#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int batch_size,
    int channels,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int pool_size,
    float s1,
    float s2) {

    int ow_idx = blockIdx.x * blockDim.x + threadIdx.x; // Each thread handles two output pixels horizontally
    int ow = ow_idx * 2;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int nc = blockIdx.z;

    if (oh < out_h && nc < batch_size * channels) {
        int n = nc / channels;
        int c = nc % channels;
        int base_idx = ((n * channels + c) * in_h);

        // Process two output pixels: (oh, ow) and (oh, ow + 1)
        if (ow < out_w) {
            float sum1 = 0.0f;
            for (int i = 0; i < pool_size; ++i) {
                int ih = oh * pool_size + i;
                if (ih < in_h) {
                    for (int j = 0; j < pool_size; ++j) {
                        int iw = ow * pool_size + j;
                        if (iw < in_w) {
                            float val = input[(base_idx + ih) * in_w + iw];
                            val = tanhf(val - s1) - s2;
                            sum1 += val;
                        }
                    }
                }
            }
            output[((n * channels + c) * out_h + oh) * out_w + ow] = sum1 / (pool_size * pool_size);
        }

        if (ow + 1 < out_w) {
            float sum2 = 0.0f;
            for (int i = 0; i < pool_size; ++i) {
                int ih = oh * pool_size + i;
                if (ih < in_h) {
                    for (int j = 0; j < pool_size; ++j) {
                        int iw = (ow + 1) * pool_size + j;
                        if (iw < in_w) {
                            float val = input[(base_idx + ih) * in_w + iw];
                            val = tanhf(val - s1) - s2;
                            sum2 += val;
                        }
                    }
                }
            }
            output[((n * channels + c) * out_h + oh) * out_w + ow + 1] = sum2 / (pool_size * pool_size);
        }
    }
}

torch::Tensor fused_ops_hip(
    torch::Tensor input,
    int pool_size,
    float s1,
    float s2) {

    int batch_size = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_h = in_h / pool_size;
    int out_w = in_w / pool_size;

    auto output = torch::empty({batch_size, channels, out_h, out_w}, input.options());

    dim3 block_dim(16, 16);
    dim3 grid_dim(((out_w + 1) / 2 + block_dim.x - 1) / block_dim.x, 
                   (out_h + block_dim.y - 1) / block_dim.y, 
                   batch_size * channels);

    fused_ops_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_h,
        in_w,
        out_h,
        out_w,
        pool_size,
        s1,
        s2
    );

    return output;
}
"""

