        out_v.y = mish_forward(in_v.y);
        out_v.z = mish_forward(in_v.z);
        out_v.w = mish_forward(in_v.w);
        reinterpret_cast<float4*>(output + idx)[0] = out_v;
    } else {
        for (int i = idx; i < size; ++i) {
            output[i] = mish_forward(input[i]);
        }
