    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    int total_elements = rows * cols;
    if (idx < total_elements) {
        float4* x_ptr = reinterpret_cast<float4*>(&x[idx]);
        const float4* b_ptr = reinterpret_cast<const float4*>(&bias[idx % cols]);

        float4 x_val = *x_ptr;
        float4 b_val = *b_ptr;

        x_val.x = (x_val.x + b_val.x) * factor;
        x_val.y = (x_val.y + b_val.y) * factor;
        x_val.z = (x_val.z + b_val.z) * factor;
        x_val.w = (x_val.w + b_val.w) * factor;

        *x_ptr = x_val;
    }
}

// Actually, the above kernel has a problem with idx % cols if cols is not a multiple of the vector length.
// But cols is 4096, which is a multiple of 4.
