#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__device__ __forceinline__ float gelu_func(float x) {
    return 0.5f * x * (1.0f + erff(x * 0.70710678118f));
}

__global__ void gelu_kernel_vec4(float* out, int total_elements) {
    int idx = (blockIdx.x * blockDim.x + threadIdx.x) * 4;
    if (idx + 3 < total_elements) {
        float4 val_vec = reinterpret_cast<float4*>(&out[idx])[0];
        float4 res;
        res.x = gelu_func(val_vec.x);
        res.y = gelu_func(val_vec.y);
        res.z = gelu_func(val_vec.z);
        res.w = gelu_func(val_vec.w);
        reinterpret_cast<float4*>(&out[idx])[0] = res;
    } else {
        for (int i = idx; i < total_elements; ++i) {
            out[i] = gelu_func(out[i]);
        }
    }
}

void gelu_vec4(torch::Tensor out) {
    int total_elements = out.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements / 4 + block_size - 1) / block_size;
    gelu_kernel_vec4<<<num_blocks, block_size>>>(out.data_ptr<float>(), total_elements);
}
"""

