    def __init__(self, input_size, output_size, divisor):
        super(ModelNew, self).__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.fused_ops = fused_ops

    def forward(self, x):
        # (bias + x @ weight.T) / divisor = (1/divisor) * bias + (1/divisor) * (x @ weight.T)
        inv_divisor = 1.0 / self.divisor
        out = torch.addmm(self.linear.bias, x, self.linear.weight.t(), beta=inv_divisor, alpha=inv_divisor)
        self.fused_ops.gelu_vec4(out)
        return out

