#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>
#include <hip/hip_fp16.h>

#define SOFTMAX_BLOCK_SIZE 256
#define ELEMENTS_PER_THREAD 32

__device__ inline float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

// Warp reduce max
__device__ inline float warpReduceMax(float val) {
    for (int offset = 32; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down(val, offset));
    return val;
}

// Warp reduce sum
__device__ inline float warpReduceSum(float val) {
    for (int offset = 32; offset > 0; offset >>= 1)
        val += __shfl_down(val, offset);
    return val;
}

__global__ void gelu_softmax_kernel(const float* __restrict__ input, float* __restrict__ output, int rows, int cols) {
    int row = blockIdx.x;
    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    float local_vals[ELEMENTS_PER_THREAD];
    float max_val = -1e20f;

    // Load and GELU
    for (int i = 0; i < ELEMENTS_PER_THREAD; ++i) {
        int col = threadIdx.x + i * SOFTMAX_BLOCK_SIZE;
        if (col < cols) {
            float val = gelu(row_input[col]);
            local_vals[i] = val;
            if (val > max_val) max_val = val;
        } else {
            local_vals[i] = -1e20f;
        }
    }

    // Block reduction for max
    __shared__ float shared_max[8]; // 256 / 32 = 8 warps
    float warp_max = warpReduceMax(max_val);
    if ((threadIdx.x & 31) == 0) shared_max[threadIdx.x / 32] = warp_max;
    __syncthreads();

    if (threadIdx.x < 8) {
        float val = shared_max[threadIdx.x];
        for (int offset = 4; offset > 0; offset >>= 1)
            val = fmaxf(val, __shfl_down(val, offset));
        if (threadIdx.x == 0) shared_max[0] = val;
    }
    __syncthreads();
    max_val = shared_max[0];

    // Exp and Sum
    float sum_val = 0.0f;
    for (int i = 0; i < ELEMENTS_PER_THREAD; ++i) {
        int col = threadIdx.x + i * SOFTMAX_BLOCK_SIZE;
        if (col < cols) {
            local_vals[i] = expf(local_vals[i] - max_val);
            sum_val += local_vals[i];
        }
    }

    // Block reduction for sum
    __shared__ float shared_sum[8];
    float warp_sum = warpReduceSum(sum_val);
    if ((threadIdx.x & 31) == 0) shared_sum[threadIdx.x / 32] = warp_sum;
    __syncthreads();

    if (threadIdx.x < 8) {
        float val = shared_sum[threadIdx.x];
        for (int offset = 4; offset > 0; offset >>= 1)
            val += __shfl_down(val, offset);
        if (threadIdx.x == 0) shared_sum[0] = val;
    }
    __syncthreads();
    sum_val = shared_sum[0];

    // Store
    float inv_sum = 1.0f / sum_val;
    for (int i = 0; i < ELEMENTS_PER_THREAD; ++i) {
        int col = threadIdx.x + i * SOFTMAX_BLOCK_SIZE;
        if (col < cols) {
            row_output[col] = local_vals[i] * inv_sum;
        }
    }
}

torch::Tensor gelu_softmax_hip(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);
    auto output = torch::empty_like(input);

    dim3 grid(rows);
    dim3 block(SOFTMAX_BLOCK_SIZE);

    hipLaunchKernelGGL(gelu_softmax_kernel, grid, block, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), rows, cols);

    return output;
}
