    dim3 grid_dim((out_w + block_dim.x - 1) / block_dim.x, 
                   (out_h + block_dim.y - 1) / block_dim.y, 
                   batch_size * channels);

    fused_ops_kernel<<<grid_dim, block_dim>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        in_h,
