fused_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fused_bias_softmax_kernel(
    float* x, 
    const float* bias, 
    int rows, 
    int cols) 
{
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Shared memory for one row
    extern __shared__ float shared_mem[];
    float* shared_row = shared_mem;

    // 1. Load data from global memory, add bias, and find local max
    float local_max = -1e38f;
    for (int col = tid; col < cols; col += num_threads) {
        float val = x[row * cols + col] + bias[col];
        shared_row[col] = val;
        if (val > local_max) local_max = val;
    }

    // Block reduction for max
    __syncthreads();
    // Using shared_row for reduction is fine as long as we don't overwrite data we still need.
    // But we need all of shared_row for the sum of exps. 
    // Let's use a separate small shared memory for the reduction.
    __shared__ float s_reduce[1024];
    s_reduce[tid] = local_max;
    __syncthreads();

    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (s_reduce[tid + s] > s_reduce[tid]) s_reduce[tid] = s_reduce[tid + s];
        }
        __syncthreads();
    }
    float max_val = s_reduce[0];
    __syncthreads();

    // 2. Compute sum of exps
    float local_sum = 0.0f;
    for (int col = tid; col < cols; col += num_threads) {
        float val = expf(shared_row[col] - max_val);
        shared_row[col] = val;
        local_sum += val;
    }

    s_reduce[tid] = local_sum;
    __syncthreads();

    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) s_reduce[tid] += s_reduce[tid + s];
        __syncthreads();
    }
    float sum_val = s_reduce[0];
    __syncthreads();

    // 3. Normalize and write back
    for (int col = tid; col < cols; col += num_threads) {
        x[row * cols + col] = shared_row[col] / sum_val;
    }
}

torch::Tensor fused_bias_softmax_hip(
    torch::Tensor x, 
    torch::Tensor bias) 
{
    int rows = x.size(0);
    int cols = x.size(1);

    const int threads_per_block = 1024;
    // shared_mem needs cols * 4 bytes.
    size_t shared_mem_size = cols * sizeof(float);

    fused_bias_softmax_kernel<<<rows, threads_per_block, shared_mem_size>>>(
        x.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        rows, 
        cols
    );

    return x;
}
"""

fused_softmax_lib = load_inline(
    name="fused_softmax_lib",
    cpp_sources=fused_softmax_source,
    functions=["fused_bias_softmax_hip"],
    verbose=True,
)

