fused_gelu_softmax_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

#define SOFTMAX_BLOCK_SIZE 256
#define WAVEFRONT_SIZE 64

__device__ inline float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

__device__ inline float warpReduceMax(float val) {
    for (int offset = WAVEFRONT_SIZE / 2; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_xor(val, offset, WAVEFRONT_SIZE));
    return val;
}

__device__ inline float warpReduceSum(float val) {
    for (int offset = WAVEFRONT_SIZE / 2; offset > 0; offset >>= 1)
        val += __shfl_xor(val, offset, WAVEFRONT_SIZE);
    return val;
}

__global__ void gelu_softmax_kernel(const float4* __restrict__ input, float4* __restrict__ output, int rows, int cols_v4) {
    int row = blockIdx.x;
    if (row >= rows) return;

    const float4* row_input = input + row * cols_v4;
    float4* row_output = output + row * cols_v4;

    float local_max = -1e20f;

    // First pass: max
    for (int i = threadIdx.x; i < cols_v4; i += SOFTMAX_BLOCK_SIZE) {
        float4 v4 = row_input[i];
        local_max = fmaxf(local_max, gelu(v4.x));
        local_max = fmaxf(local_max, gelu(v4.y));
        local_max = fmaxf(local_max, gelu(v4.z));
        local_max = fmaxf(local_max, gelu(v4.w));
    }

    __shared__ float shared_max[SOFTMAX_BLOCK_SIZE / WAVEFRONT_SIZE];
    float w_max = warpReduceMax(local_max);
    if ((threadIdx.x % WAVEFRONT_SIZE) == 0) shared_max[threadIdx.x / WAVEFRONT_SIZE] = w_max;
    __syncthreads();

    float max_val = shared_max[0];
    for (int i = 1; i < (SOFTMAX_BLOCK_SIZE / WAVEFRONT_SIZE); ++i) {
        max_val = fmaxf(max_val, shared_max[i]);
    }

    // Second pass: sum
    float local_sum = 0.0f;
    for (int i = threadIdx.x; i < cols_v4; i += SOFTMAX_BLOCK_SIZE) {
        float4 v4 = row_input[i];
        local_sum += expf(gelu(v4.x) - max_val);
        local_sum += expf(gelu(v4.y) - max_val);
        local_sum += expf(gelu(v4.z) - max_val);
        local_sum += expf(gelu(v4.w) - max_val);
    }

    __shared__ float shared_sum[SOFTMAX_BLOCK_SIZE / WAVEFRONT_SIZE];
    float w_sum = warpReduceSum(local_sum);
    if ((threadIdx.x % WAVEFRONT_SIZE) == 0) shared_sum[threadIdx.x / WAVEFRONT_SIZE] = w_sum;
    __syncthreads();

    float sum_val = shared_sum[0];
    for (int i = 1; i < (SOFTMAX_BLOCK_SIZE / WAVEFRONT_SIZE); ++i) {
        sum_val += shared_sum[i];
    }
    float inv_sum = 1.0f / sum_val;

    // Third pass: compute and store
    for (int i = threadIdx.x; i < cols_v4; i += SOFTMAX_BLOCK_SIZE) {
        float4 v4 = row_input[i];
        v4.x = expf(gelu(v4.x) - max_val) * inv_sum;
        v4.y = expf(gelu(v4.y) - max_val) * inv_sum;
        v4.z = expf(gelu(v4.z) - max_val) * inv_sum;
        v4.w = expf(gelu(v4.w) - max_val) * inv_sum;
        row_output[i] = v4;
    }
}

torch::Tensor gelu_softmax_hip(torch::Tensor input) {
    int rows = input.size(0);
    int cols = input.size(1);
    int cols_v4 = cols / 4;
    auto output = torch::empty_like(input);

    dim3 grid(rows);
    dim3 block(SOFTMAX_BLOCK_SIZE);

    hipLaunchKernelGGL(gelu_softmax_kernel, grid, block, 0, 0, (const float4*)input.data_ptr<float>(), (float4*)output.data_ptr<float>(), rows, cols_v4);

    return output;
}
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_gelu_softmax_source,
    functions=["gelu_softmax_hip"],
    verbose=True,
)

