fused_op_cpp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <float.h>

__global__ void fused_op_kernel_v3(const float* __restrict__ Z, float* __restrict__ out, 
                                   int batch_size, int out_features, int kernel_size, float scale_factor) {
    // Each block handles a portion of the pooled_features for a single batch element
    // gridDim.x = batch_size, gridDim.y = num_blocks_per_batch
    int b = blockIdx.x;
    int tid = threadIdx.x;
    int block_y = blockIdx.y;
    int num_blocks_y = gridDim.y;
    int num_threads = blockDim.x;

    int pooled_features = out_features / kernel_size;

    // Each block computes a partial sum for its portion of the features
    int chunk_size = (pooled_features + num_blocks_y - 1) / num_blocks_y;
    int start_i = block_y * chunk_size;
    int end_i = min(start_i + chunk_size, pooled_features);

    float local_sum = 0.0f;
    for (int i = start_i + tid; i < end_i; i += num_threads) {
        float max_val = -FLT_MAX;
        for (int k = 0; k < kernel_size; ++k) {
            int idx = i * kernel_size + k;
            float val = Z[b * out_features + idx];
            if (val > max_val) {
                max_val = val;
            }
        }
        local_sum += max_val;
    }

    // Shared memory reduction
    extern __shared__ float shared_data[];
    shared_data[tid] = local_sum;
    __syncthreads();

    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        // Atomic add to the output
        atomicAdd(&out[b], shared_data[0] * scale_factor);
    }
}

torch::Tensor fused_op_hip_v3(torch::Tensor Z, int kernel_size, float scale_factor) {
    auto batch_size = Z.size(0);
    auto out_features = Z.size(1);
    auto out = torch::zeros({batch_size}, Z.options());

    int num_blocks_per_batch = 16;
    dim3 grid(batch_size, num_blocks_per_batch);
    const int block_size = 256;

    fused_op_kernel_v3<<<grid, block_size, block_size * sizeof(float)>>>(
        Z.data_ptr<float>(), out.data_ptr<float>(), 
        batch_size, out_features, kernel_size, scale_factor);

    return out;
}
"""

