#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <math.h>

__global__ void fast_softmax_kernel(float* x, int rows, int cols) {
    int row = blockIdx.x;
    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    // Use a large enough local buffer for registers.
    // Since cols=16384 and num_threads=1024, each thread needs 16 floats.
    float vals[16];
    float max_val = -1e38f;

    for (int i = 0; i < 16; ++i) {
        int col = tid + i * num_threads;
        if (col < cols) {
            float v = x[row * cols + col];
            vals[i] = v;
            if (v > max_val) max_val = v;
        }
    }

    // Block reduction for max
    __shared__ float s_reduce[1024];
    s_reduce[tid] = max_val;
    __syncthreads();
    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            if (s_reduce[tid + s] > s_reduce[tid]) s_reduce[tid] = s_reduce[tid + s];
        }
        __syncthreads();
    }
    max_val = s_reduce[0];
    __syncthreads();

    float sum_val = 0.0f;
    for (int i = 0; i < 16; ++i) {
        vals[i] = expf(vals[i] - max_val);
        sum_val += vals[i];
    }

    s_reduce[tid] = sum_val;
    __syncthreads();
    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) s_reduce[tid] += s_reduce[tid + s];
        __syncthreads();
    }
    sum_val = s_reduce[0];
    __syncthreads();

    for (int i = 0; i < 16; ++i) {
        int col = tid + i * num_threads;
        if (col < cols) {
            x[row * cols + col] = vals[i] / sum_val;
        }
    }
}

torch::Tensor fast_softmax_hip(torch::Tensor x) {
    int rows = x.size(0);
    int cols = x.size(1);
    const int threads_per_block = 1024;
    fast_softmax_kernel<<<rows, threads_per_block>>>(x.data_ptr<float>(), rows, cols);
    return x;
}
"""

