#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void instance_norm_divide_kernel_simple(
    float* __restrict__ input,
    int N, int C, int H, int W,
    float eps, float divide_by) {

    int nc = blockIdx.x;
    int hw_size = H * W;
    float* input_ptr = input + nc * hw_size;

    double sum = 0.0;
    double sum_sq = 0.0;

    for (int i = threadIdx.x; i < hw_size; i += blockDim.x) {
        float val = input_ptr[i];
        sum += (double)val;
        sum_sq += (double)val * (double)val;
    }

    extern __shared__ double shared_data[];
    double* s_sum = shared_data;
    double* s_sum_sq = shared_data + blockDim.x;

    s_sum[threadIdx.x] = sum;
    s_sum_sq[threadIdx.x] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sum_sq[threadIdx.x] += s_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = (float)(s_sum[0] / hw_size);
    float var = (float)((s_sum_sq[0] / hw_size) - (double)mean * (double)mean);
    if (var < 0.0f) var = 0.0f;
    float inv_std = 1.0f / (sqrtf(var + eps) * divide_by);

