#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>
#include <algorithm>

__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 8; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_down(val, offset, 16));
    }
    // Note: This only works if we're only looking at the first 16 threads in a 16-thread group.
    // The value will be correct in the first thread of the 16-thread group.
    return __shfl(val, 0, 16);
}

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 8; offset > 0; offset /= 2) {
        val += __shfl_down(val, offset, 16);
    }
    return __shfl(val, 0, 16);
}

__global__ void softmax_maxpool_kernel_nhwc_v3(
    const float* __restrict__ input,
    float* __restrict__ output,
    int total_spatial_out,
    int in_d, int in_h, int in_w,
    int out_d, int out_h, int out_w) 
{
    // Each thread handles one (batch, channel, d_out, h_out, w_out)
    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements_out = total_spatial_out * 16;

    if (tid < total_elements_out) {
        int c_idx = tid % 16;
        int spatial_idx = tid / 16;
        int w_out_idx = spatial_idx % out_w;
        int h_out_idx = (spatial_idx / out_w) % out_h;
        int d_out_idx = (spatial_idx / (out_w * out_h)) % out_d;
        int b_idx = spatial_idx / (out_w * out_h * out_d);

        float max_pool_val = -1.0e30f;

        for (int i = 0; i < 4; ++i) {
            int d_in_idx = d_out_idx * 4 + i;
            if (d_in_idx >= in_d) continue;
            for (int j = 0; j < 4; ++j) {
                int h_in_idx = h_out_idx * 4 + j;
                if (h_in_idx >= in_h) continue;
                for (int k = 0; k < 4; ++k) {
                    int w_in_idx = w_out_idx * 4 + k;
                    if (w_in_idx >= in_w) continue;

                    int in_idx = (((b_idx * in_d + d_in_idx) * in_h + h_in_idx) * in_w + w_in_idx) * 16 + c_idx;
                    float val = input[in_idx];

                    // Softmax across 16 threads
                    float max_c = warp_reduce_max(val);
                    float ev = __expf(val - max_c);
                    float sum_ev = warp_reduce_sum(ev);
                    float softmax_val = ev / sum_ev;

                    if (softmax_val > max_pool_val) {
                        max_pool_val = softmax_val;
                    }
                }
            }
        }

        // Output in NDHWC format
        output[tid] = max_pool_val;
    }
}

