#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int pool_size,
    float s1,
    float s2) {

    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh = blockIdx.y * blockDim.y + threadIdx.y;
    int nc = blockIdx.z;

    if (ow < out_w && oh < out_h) {
        int in_base = nc * in_h * in_w;
        float sum = 0.0f;
        if (pool_size == 2) {
            int ih0 = oh * 2;
            int ih1 = ih0 + 1;
            int iw0 = ow * 2;
            int iw1 = iw0 + 1;
            int row0 = in_base + ih0 * in_w;
            int row1 = in_base + ih1 * in_w;

            sum += tanhf(input[row0 + iw0] - s1);
            sum += tanhf(input[row0 + iw1] - s1);
            sum += tanhf(input[row1 + iw0] - s1);
            sum += tanhf(input[row1 + iw1] - s1);
            output[(nc * out_h + oh) * out_w + ow] = sum * 0.25f - s2;
        } else {
            for (int i = 0; i < pool_size; ++i) {
                int ih = oh * pool_size + i;
                int row_base = in_base + ih * in_w;
                for (int j = 0; j < pool_size; ++j) {
                    int iw = ow * pool_size + j;
                    sum += tanhf(input[row_base + iw] - s1);
                }
            }
            output[(nc * out_h + oh) * out_w + ow] = sum / (float)(pool_size * pool_size) - s2;
        }
    }
}

