#include <hip/hip_runtime.h>
#include <torch/extension.h>

__global__ void final_op_kernel(const float* __restrict__ Z_sum, const float* __restrict__ Z_prime, float* __restrict__ out, 
                                int batch_size, int half_n, float final_scale) {
    int b = blockIdx.x;
    if (b >= batch_size) return;

    float abs_sum = 0.0f;
    for (int j = 0; j < half_n; ++j) {
        abs_sum += fabsf(Z_prime[b * half_n + j]);
    }

    out[b] = (Z_sum[b] + abs_sum) * final_scale;
}

// Optimized with shared memory reduction
__global__ void final_op_kernel_v2(const float* __restrict__ Z_sum, const float* __restrict__ Z_prime, float* __restrict__ out, 
                                   int batch_size, int half_n, float final_scale) {
    extern __shared__ float shared_data[];
    int b = blockIdx.x;
    int tid = threadIdx.x;
    int num_threads = blockDim.x;

    float local_abs_sum = 0.0f;
    for (int j = tid; j < half_n; j += num_threads) {
        local_abs_sum += fabsf(Z_prime[b * half_n + j]);
    }

    shared_data[tid] = local_abs_sum;
    __syncthreads();

    for (int s = num_threads / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_data[tid] += shared_data[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[b] = (Z_sum[b] + shared_data[0]) * final_scale;
    }
}

