__global__ void fused_ops_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int in_h,
    int in_w,
    int out_h,
    int out_w,
    int pool_size,
    float s1,
    float s2) {

    int ow = blockIdx.x * blockDim.x + threadIdx.x;
    int oh_nc = blockIdx.y;
    int oh = oh_nc % out_h;
    int nc = oh_nc / out_h;

    if (ow < out_w) {
